--
-- Table structure for table `inventory_transactions`
--

DROP TABLE IF EXISTS `inventory_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `variant_id` bigint unsigned NOT NULL,
  `transaction_type` varchar(30) NOT NULL,
  `quantity_change` int NOT NULL,
  `quantity_before` int unsigned NOT NULL,
  `quantity_after` int unsigned NOT NULL,
  `reference_type` varchar(50) DEFAULT NULL,
  `reference_id` bigint unsigned DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_inventory_transactions_variant_id` (`variant_id`),
  KEY `ix_inventory_transactions_transaction_type` (`transaction_type`),
  KEY `ix_inventory_transactions_created_at` (`created_at`),
  CONSTRAINT `inventory_transactions_ibfk_1` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `ck_inventory_transactions_quantity_after` CHECK ((`quantity_after` >= 0)),
  CONSTRAINT `ck_inventory_transactions_quantity_before` CHECK ((`quantity_before` >= 0)),
  CONSTRAINT `ck_inventory_transactions_transaction_type` CHECK ((`transaction_type` in (_utf8mb4'IMPORT',_utf8mb4'ORDER_RESERVE',_utf8mb4'ORDER_DEDUCT',_utf8mb4'CANCEL_RELEASE',_utf8mb4'ADJUST')))
) ENGINE=InnoDB AUTO_INCREMENT=1066 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

