  CONSTRAINT `moderation_logs_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `moderation_logs_ibfk_3` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`id`),
  CONSTRAINT `ck_moderation_logs_action` CHECK ((`action` in (_utf8mb4'HIDE_PRODUCT',_utf8mb4'DELETE_PRODUCT',_utf8mb4'LOCK_SELLER',_utf8mb4'REJECT_REPORT')))
