--
-- Table structure for table `order_cancellations`
--

DROP TABLE IF EXISTS `order_cancellations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_cancellations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `cancelled_by_user_id` bigint unsigned DEFAULT NULL,
  `cancelled_by_type` varchar(30) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_id` (`order_id`),
  KEY `cancelled_by_user_id` (`cancelled_by_user_id`),
  CONSTRAINT `order_cancellations_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `order_cancellations_ibfk_2` FOREIGN KEY (`cancelled_by_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_order_cancellations_cancelled_by_type` CHECK ((`cancelled_by_type` in (_utf8mb4'CUSTOMER',_utf8mb4'SELLER',_utf8mb4'SYSTEM')))
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
