--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(36) NOT NULL,
  `order_code` varchar(50) NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `seller_id` bigint unsigned NOT NULL,
  `order_status` varchar(30) NOT NULL,
  `payment_status` varchar(30) NOT NULL,
  `seller_confirmed` tinyint(1) NOT NULL DEFAULT '0',
  `seller_confirmed_at` datetime DEFAULT NULL,
  `subtotal_amount` decimal(12,2) NOT NULL,
  `shipping_fee` decimal(12,2) NOT NULL DEFAULT (0.00),
  `product_discount_amount` decimal(12,2) NOT NULL DEFAULT (0.00),
  `shipping_discount_amount` decimal(12,2) NOT NULL DEFAULT (0.00),
  `total_amount` decimal(12,2) NOT NULL,
  `customer_note` varchar(500) DEFAULT NULL,
  `print_count` int NOT NULL DEFAULT '0',
  `payment_expires_at` datetime NOT NULL,
  `seller_confirm_expires_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `preferred_payment_method` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_id` (`public_id`),
  UNIQUE KEY `order_code` (`order_code`),
  KEY `ix_orders_seller_confirm_expires_at` (`seller_confirm_expires_at`),
  KEY `ix_orders_order_status` (`order_status`),
  KEY `ix_orders_seller_id` (`seller_id`),
  KEY `ix_orders_user_id` (`user_id`),
  KEY `ix_orders_payment_status` (`payment_status`),
  KEY `ix_orders_created_at` (`created_at`),
  KEY `ix_orders_payment_expires_at` (`payment_expires_at`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`id`),
  CONSTRAINT `ck_orders_order_status` CHECK ((`order_status` in (_utf8mb4'PLACED',_utf8mb4'READY_TO_SHIP',_utf8mb4'SHIPPING',_utf8mb4'COMPLETED',_utf8mb4'DELIVERY_FAILED',_utf8mb4'CANCELLED'))),
  CONSTRAINT `ck_orders_payment_status` CHECK ((`payment_status` in (_utf8mb4'PENDING',_utf8mb4'PAID',_utf8mb4'FAILED',_utf8mb4'CANCELLED',_utf8mb4'REFUND_PENDING',_utf8mb4'REFUNDED'))),
  CONSTRAINT `ck_orders_product_discount_amount` CHECK ((`product_discount_amount` >= 0)),
  CONSTRAINT `ck_orders_shipping_discount_amount` CHECK ((`shipping_discount_amount` >= 0)),
  CONSTRAINT `ck_orders_shipping_fee` CHECK ((`shipping_fee` >= 0)),
  CONSTRAINT `ck_orders_subtotal_amount` CHECK ((`subtotal_amount` >= 0)),
  CONSTRAINT `ck_orders_total_amount` CHECK ((`total_amount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=597 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

